mapper.select:
SELECT s.forward_id AS forwardId, COALESCE(MAX(f.name), MAX(s.name)) AS name, COALESCE(MAX(f.in_port), MAX(s.in_port)) AS inPort, COALESCE(MAX(f.out_port), MAX(s.out_port)) AS outPort, MAX(s.user_id) AS userId, MAX(f.user_name) AS userName, COALESCE(MAX(f.tunnel_id), MAX(s.tunnel_id)) AS tunnelId, MAX(t.name) AS tunnelName, SUM(s.flow) AS flow, MAX(f.status) AS status, SUM(s.flow) AS inFlow, 0 AS outFlow FROM statistics_flow_forward s LEFT JOIN forward f ON f.id = s.forward_id LEFT JOIN tunnel t ON t.id = COALESCE(f.tunnel_id, s.tunnel_id) WHERE s.created_time >= #{startTime}
AND s.user_id = #{userId}
GROUP BY s.forward_id HAVING SUM(s.flow) > 0 ORDER BY SUM(s.flow) DESC LIMIT #{limit}
